import type { Context } from "hono"

import consola from "consola"
import { type SSEMessage } from "hono/streaming"

import { awaitApproval } from "~/lib/approval"
import { resolveEffort } from "~/lib/effort"
import { resolveEndpoint } from "~/lib/endpoint-routing"
import { checkRateLimit } from "~/lib/rate-limit"
import { state } from "~/lib/state"
import { streamSSEWithAbort, writeOpenAIStreamError } from "~/lib/streaming"
import { getTokenCount } from "~/lib/tokenizer"
import { isNullish } from "~/lib/utils"
import {
  createChatCompletions,
  type ChatCompletionChunk,
  type ChatCompletionsPayload,
} from "~/services/copilot/create-chat-completions"
import {
  createResponses,
  createResponsesStreamState,
  translateResponsesStreamEvent,
} from "~/services/copilot/create-responses"

export async function handleCompletion(c: Context) {
  await checkRateLimit(state)

  let payload = await c.req.json<ChatCompletionsPayload>()
  consola.debug("Request payload:", JSON.stringify(payload).slice(-400))

  // Find the selected model
  const selectedModel = state.models?.data.find(
    (model) => model.id === payload.model,
  )

  // Calculate and display token count
  try {
    if (selectedModel) {
      const tokenCount = await getTokenCount(payload, selectedModel)
      consola.info("Current token count:", tokenCount)
    } else {
      consola.warn("No model selected, skipping token count calculation")
    }
  } catch (error) {
    consola.warn("Failed to calculate token count:", error)
  }

  if (state.manualApprove) await awaitApproval()

  // Upstream rejects a request carrying both token controls, so only supply a
  // catalog default when the client expressed neither.
  const hasClientTokenLimit =
    !isNullish(payload.max_tokens) || !isNullish(payload.max_completion_tokens)

  if (!hasClientTokenLimit) {
    payload = {
      ...payload,
      max_tokens: selectedModel?.capabilities.limits?.max_output_tokens,
    }
    consola.debug("Set max_tokens to:", JSON.stringify(payload.max_tokens))
  }

  const endpoint = resolveEndpoint(payload.model, state.models)
  const signal = c.req.raw.signal

  // Route to /responses for GPT-5.x and models that only support it
  if (endpoint === "/responses") {
    consola.debug(`Using /responses endpoint for model: ${payload.model}`)
    return handleResponsesEndpoint(c, payload, signal)
  }

  payload.reasoning_effort = resolveEffort({
    modelId: payload.model,
    requested: payload.reasoning_effort,
    cachedModels: state.models,
  })

  // Existing /chat/completions path
  const result = await createChatCompletions(payload, signal)

  if (result.kind === "object") {
    consola.debug("Non-streaming response:", JSON.stringify(result.body))
    return c.json(result.body)
  }
  const response = result.stream

  consola.debug("Streaming response")
  let terminalErrorSeen = false
  return streamSSEWithAbort(
    c,
    {
      signal,
      label: "chat-completions",
      onError: writeOpenAIStreamError,
      hasTerminalError: () => terminalErrorSeen,
    },
    async (stream) => {
      for await (const chunk of response) {
        consola.debug("Streaming chunk:", JSON.stringify(chunk))
        terminalErrorSeen ||= Boolean((chunk as ChatCompletionChunk).error)
        await stream.writeSSE(chunk as SSEMessage)
      }
    },
  )
}

async function handleResponsesEndpoint(
  c: Context,
  payload: ChatCompletionsPayload,
  signal?: AbortSignal,
) {
  const effort = resolveEffort({
    modelId: payload.model,
    requested: payload.reasoning_effort,
    cachedModels: state.models,
    defaultEffort: "medium",
  })
  const result = await createResponses(payload, effort, signal)

  if (result.kind === "object") {
    consola.debug(
      "Non-streaming /responses result:",
      JSON.stringify(result.body),
    )
    return c.json(result.body)
  }
  const response = result.stream

  consola.debug("Streaming /responses response")
  let terminalErrorSeen = false
  return streamSSEWithAbort(
    c,
    {
      signal,
      label: "/responses",
      onError: writeOpenAIStreamError,
      hasTerminalError: () => terminalErrorSeen,
    },
    async (stream) => {
      const streamState = createResponsesStreamState()

      for await (const rawEvent of response) {
        if (!rawEvent.data || rawEvent.data === "[DONE]") continue

        const parsed = JSON.parse(rawEvent.data) as Record<string, unknown>
        const eventType =
          rawEvent.event ?? (parsed.type as string | undefined) ?? ""

        const chunks = translateResponsesStreamEvent(
          { event: eventType, data: parsed },
          streamState,
        )

        for (const chunk of chunks) {
          consola.debug("Translated /responses chunk:", JSON.stringify(chunk))
          terminalErrorSeen ||= Boolean(chunk.error)
          await stream.writeSSE({
            data: JSON.stringify(chunk),
          })
        }
      }
    },
  )
}

import type { ContentfulStatusCode } from "hono/utils/http-status"

import { Hono } from "hono"

import { state } from "~/lib/state"
import {
  createEmbeddings,
  type EmbeddingRequest,
} from "~/services/copilot/create-embeddings"

export const embeddingRoutes = new Hono()

type ErrorBody = ReturnType<typeof errorResponse>
type ValidationResult = { payload: EmbeddingRequest } | { error: ErrorBody }

function errorResponse(
  message: string,
  param: string | null,
  code = "invalid_value",
) {
  return { error: { type: "invalid_request_error", code, message, param } }
}

function validateInput(value: unknown): Array<string> | ErrorBody {
  const values = typeof value === "string" ? [value] : value
  if (
    !Array.isArray(values)
    || values.length === 0
    || values.some((item) => typeof item !== "string" || item.length === 0)
  ) {
    return errorResponse(
      "input must be a non-empty string or array of non-empty strings",
      "input",
    )
  }
  return values as Array<string>
}

function validateOptions(
  input: Record<string, unknown>,
  values: Array<string>,
): ErrorBody | undefined {
  const model = state.models?.data.find((item) => item.id === input.model)
  if (!model || model.capabilities.type !== "embeddings") {
    return errorResponse(
      `Model ${String(input.model)} is not an available embedding model`,
      "model",
      "model_not_found",
    )
  }
  const maxInputs = model.capabilities.limits?.max_inputs
  if (maxInputs && values.length > maxInputs) {
    return errorResponse(
      `input contains ${values.length} items; model limit is ${maxInputs}`,
      "input",
    )
  }
  if (
    input.dimensions !== undefined
    && (!Number.isInteger(input.dimensions) || Number(input.dimensions) <= 0)
  ) {
    return errorResponse("dimensions must be a positive integer", "dimensions")
  }
  if (
    input.dimensions !== undefined
    && !model.capabilities.supports.dimensions
  ) {
    return errorResponse(
      `Model ${String(input.model)} does not support dimensions`,
      "dimensions",
    )
  }
  if (
    input.encoding_format !== undefined
    && input.encoding_format !== "float"
  ) {
    return errorResponse(
      'encoding_format must be "float"; base64 is not supported',
      "encoding_format",
    )
  }
}

function validatePayload(value: unknown): ValidationResult {
  if (!value || typeof value !== "object") {
    return { error: errorResponse("Request body must be an object", null) }
  }
  const input = value as Record<string, unknown>
  if (typeof input.model !== "string" || input.model.length === 0) {
    return { error: errorResponse("model must be a non-empty string", "model") }
  }
  const values = validateInput(input.input)
  if (!Array.isArray(values)) return { error: values }
  const optionsError = validateOptions(input, values)
  if (optionsError) return { error: optionsError }

  return {
    payload: {
      model: input.model,
      input: values,
      dimensions: input.dimensions as number | undefined,
      encoding_format: input.encoding_format as "float" | undefined,
    },
  }
}

function copySafeHeaders(
  response: Response,
  set: (name: string, value: string) => void,
) {
  for (const name of [
    "x-copilot-service-request-id",
    "x-github-request-id",
    "retry-after",
  ]) {
    const value = response.headers.get(name)
    if (value) set(name, value)
  }
}

async function upstreamError(response: Response): Promise<ErrorBody> {
  const text = await response.text()
  let envelope: Record<string, unknown> | undefined
  try {
    const parsed = JSON.parse(text) as { error?: Record<string, unknown> }
    envelope = parsed.error
  } catch {
    envelope = undefined
  }
  return {
    error: {
      type:
        typeof envelope?.type === "string" ? envelope.type : "upstream_error",
      code:
        typeof envelope?.code === "string" ?
          envelope.code
        : "embedding_request_failed",
      message:
        typeof envelope?.message === "string" ?
          envelope.message
        : text.trim()
          || `Upstream embeddings request failed (${response.status})`,
      param: typeof envelope?.param === "string" ? envelope.param : null,
    },
  }
}

embeddingRoutes.post("/", async (c) => {
  let value: unknown
  try {
    value = await c.req.json()
  } catch {
    return c.json(errorResponse("Request body must be valid JSON", null), 400)
  }
  const validated = validatePayload(value)
  if ("error" in validated) return c.json(validated.error, 400)

  const response = await createEmbeddings(validated.payload, c.req.raw.signal)
  copySafeHeaders(response, (name, header) => c.header(name, header))
  if (!response.ok) {
    return c.json(
      await upstreamError(response),
      response.status as ContentfulStatusCode,
    )
  }

  const result = (await response.json()) as Record<string, unknown>
  return c.json({
    ...result,
    object: "list",
    model: validated.payload.model,
  })
})

import type { ChatCompletionsPayload } from "~/services/copilot/create-chat-completions"
import type { Model } from "~/services/copilot/get-models"

export type ProbeCaseName =
  | "control"
  | "prompt-over"
  | "combined-over"
  | "output-over"

export interface ProbeCase {
  name: ProbeCaseName
  targetInputTokens: number
  requestedOutputTokens: number
  expectation: "accept" | "reject" | "not-applicable"
  reason?: string
}

export interface CopilotUsage {
  token_details: Array<{
    batch_size: number
    cost_per_batch: number
    token_count: number
    token_type: string
  }>
  total_nano_aiu: number
}

export interface ProbeResult {
  case: ProbeCaseName
  dimension: "direct" | "proxy"
  status: number | null
  ok: boolean
  error?: string
  usage?: Record<string, unknown>
  copilotUsage?: CopilotUsage
  durationMs: number
  headers: Record<string, string>
}

export function buildProbeCases(model: Model, margin = 32): Array<ProbeCase> {
  const limits = model.capabilities.limits
  const context = limits?.max_context_window_tokens
  const prompt = limits?.max_prompt_tokens
  const output = limits?.max_output_tokens
  if (!context || !prompt || !output) {
    throw new Error(`Model ${model.id} has incomplete context limits`)
  }

  const combinedInput = context - output + margin
  const combinedApplicable = combinedInput <= prompt && combinedInput > 0

  return [
    {
      name: "control",
      targetInputTokens: Math.min(512, Math.max(32, prompt - margin)),
      requestedOutputTokens: Math.min(16, output),
      expectation: "accept",
    },
    {
      name: "prompt-over",
      targetInputTokens: prompt + margin,
      requestedOutputTokens: Math.min(16, output),
      expectation: "reject",
    },
    {
      name: "combined-over",
      targetInputTokens: combinedApplicable ? combinedInput : 0,
      requestedOutputTokens: combinedApplicable ? output : 0,
      expectation: combinedApplicable ? "reject" : "not-applicable",
      reason:
        combinedApplicable ? undefined : (
          "No prompt/output pair can exceed context while both stay within advertised limits"
        ),
    },
    {
      name: "output-over",
      targetInputTokens: Math.min(128, Math.max(32, prompt - margin)),
      requestedOutputTokens: output + margin,
      expectation: "reject",
    },
  ]
}

export function makePrompt(units: number): string {
  return Array.from(
    { length: Math.max(1, units) },
    (_, index) =>
      `boundary_${index.toString(36)} value_${(index * 7919).toString(36)}`,
  ).join(" ")
}

export async function calibratePrompt(
  targetTokens: number,
  count: (content: string) => Promise<number>,
): Promise<{ content: string; estimatedTokens: number }> {
  let low = 1
  let high = Math.max(2, targetTokens)
  while ((await count(makePrompt(high))) < targetTokens) high *= 2

  while (low < high) {
    const middle = Math.floor((low + high) / 2)
    if ((await count(makePrompt(middle))) < targetTokens) low = middle + 1
    else high = middle
  }

  const candidates = [Math.max(1, low - 1), low]
  const measured = await Promise.all(
    candidates.map(async (units) => {
      const content = makePrompt(units)
      return { content, estimatedTokens: await count(content) }
    }),
  )
  return measured.reduce((best, item) =>
    (
      Math.abs(item.estimatedTokens - targetTokens)
      < Math.abs(best.estimatedTokens - targetTokens)
    ) ?
      item
    : best,
  )
}

export function buildChatPayload(
  model: string,
  content: string,
  outputTokens: number,
): ChatCompletionsPayload {
  return {
    model,
    messages: [{ role: "user", content }],
    max_tokens: outputTokens,
    stream: false,
  }
}

function isTransient(result: ProbeResult): boolean {
  return result.status === null || result.status === 429 || result.status >= 500
}

export function classifyPair(
  direct: ProbeResult | undefined,
  proxy: ProbeResult | undefined,
): string {
  if (!direct || !proxy || isTransient(direct) || isTransient(proxy)) {
    return "inconclusive"
  }
  if (direct.ok && proxy.ok) return "accepted-by-upstream"
  if (!direct.ok && !proxy.ok) return "both-enforced"
  if (!direct.ok && proxy.ok) return "proxy-preflight-or-workaround"
  if (direct.ok && !proxy.ok) return "proxy-regression"
  return "inconclusive"
}

export function extractUsage(
  body: unknown,
): Record<string, unknown> | undefined {
  if (!body || typeof body !== "object") return undefined
  const usage = (body as Record<string, unknown>).usage
  return usage && typeof usage === "object" ?
      (usage as Record<string, unknown>)
    : undefined
}

export function extractCopilotUsage(body: unknown): CopilotUsage | undefined {
  if (!body || typeof body !== "object") return undefined
  const usage = (body as Record<string, unknown>).copilot_usage
  if (!usage || typeof usage !== "object") return undefined
  const record = usage as Record<string, unknown>
  return (
      Array.isArray(record.token_details)
        && typeof record.total_nano_aiu === "number"
    ) ?
      (record as unknown as CopilotUsage)
    : undefined
}

export function calculateNanoAiu(usage: CopilotUsage): number {
  return usage.token_details.reduce(
    (total, detail) =>
      total + (detail.token_count * detail.cost_per_batch) / detail.batch_size,
    0,
  )
}

export function nanoAiuToAiu(nanoAiu: number): number {
  return nanoAiu / 1_000_000_000
}

export function creditDelta(
  before: unknown,
  after: unknown,
): number | undefined {
  const read = (value: unknown): number | undefined => {
    if (!value || typeof value !== "object") return undefined
    const snapshots = (value as Record<string, unknown>).quota_snapshots
    if (!snapshots || typeof snapshots !== "object") return undefined
    const premium = (snapshots as Record<string, unknown>).premium_interactions
    if (!premium || typeof premium !== "object") return undefined
    const credits = (premium as Record<string, unknown>).credits_used
    return typeof credits === "number" ? credits : undefined
  }
  const start = read(before)
  const end = read(after)
  return start === undefined || end === undefined ? undefined : end - start
}

#!/usr/bin/env bun

import { mkdir, readFile, writeFile } from "node:fs/promises"
import { homedir } from "node:os"
import { join } from "node:path"

import type { Model, ModelsResponse } from "~/services/copilot/get-models"

import { copilotHeaders } from "~/lib/api-config"
import { resolveEndpoint } from "~/lib/endpoint-routing"
import { state } from "~/lib/state"
import { getTokenCount } from "~/lib/tokenizer"
import { getCopilotToken } from "~/services/github/get-copilot-token"

import {
  buildChatPayload,
  buildProbeCases,
  calibratePrompt,
  classifyPair,
  creditDelta,
  extractCopilotUsage,
  extractUsage,
  nanoAiuToAiu,
  type ProbeCase,
  type ProbeResult,
} from "./lib/context-boundary"

const args = process.argv.slice(2)
const execute = args.includes("--execute")
const modelArg = args.find((arg) => arg.startsWith("--model="))?.slice(8)
const via = args.find((arg) => arg.startsWith("--via="))?.slice(6) ?? "both"
const margin = Number(
  args.find((arg) => arg.startsWith("--margin="))?.slice(9) ?? 512,
)
const timeoutMs = Number(
  args.find((arg) => arg.startsWith("--timeout="))?.slice(10) ?? 120_000,
)
const proxyUrl = (
  args.find((arg) => arg.startsWith("--proxy-url="))?.slice(12)
  ?? "http://localhost:4141"
).replace(/\/$/, "")
let directBaseUrl = "https://api.githubcopilot.com"
const selectedCases = new Set(
  (
    args.find((arg) => arg.startsWith("--cases="))?.slice(8)
    ?? "control,prompt-over,combined-over,output-over"
  ).split(","),
)

if (!new Set(["direct", "proxy", "both"]).has(via)) {
  throw new Error("--via must be direct, proxy, or both")
}
if (!Number.isFinite(margin) || margin < 1)
  throw new Error("--margin must be positive")
if (!Number.isFinite(timeoutMs) || timeoutMs < 1)
  throw new Error("--timeout must be positive")

async function fetchJson(
  url: string,
  init?: RequestInit,
): Promise<{ response: Response; body: unknown; text: string }> {
  const response = await fetch(url, {
    ...init,
    signal: AbortSignal.timeout(timeoutMs),
  })
  const text = await response.text()
  let body: unknown
  try {
    body = JSON.parse(text)
  } catch {
    body = undefined
  }
  return { response, body, text }
}

function hasCompleteLimits(model: Model): boolean {
  const unsafeModel = model as { capabilities?: Model["capabilities"] }
  const limits = unsafeModel.capabilities?.limits
  return Boolean(
    limits?.max_context_window_tokens
      && limits.max_prompt_tokens
      && limits.max_output_tokens,
  )
}

function chooseModel(models: ModelsResponse): Model {
  const eligible = models.data
    .filter((model) => hasCompleteLimits(model))
    .sort(
      (a, b) =>
        (a.capabilities.limits?.max_context_window_tokens ?? Infinity)
        - (b.capabilities.limits?.max_context_window_tokens ?? Infinity),
    )
  const model =
    modelArg ?
      eligible.find((item) => item.id === modelArg)
    : eligible.find((item) => item.model_picker_enabled)
  if (!model)
    throw new Error(`No eligible model found${modelArg ? `: ${modelArg}` : ""}`)
  return model
}

function directBody(
  model: Model,
  content: string,
  outputTokens: number,
): { url: string; body: unknown } {
  const endpoint = resolveEndpoint(model.id, { object: "list", data: [model] })
  if (endpoint === "/responses") {
    return {
      url: `${directBaseUrl}/responses`,
      body: {
        model: model.id,
        input: [{ type: "message", role: "user", content }],
        max_output_tokens: outputTokens,
        reasoning: { effort: "low" },
        stream: false,
      },
    }
  }
  if (endpoint === "/v1/messages") {
    return {
      url: `${directBaseUrl}/v1/messages`,
      body: {
        model: model.id,
        messages: [{ role: "user", content }],
        max_tokens: outputTokens,
        stream: false,
      },
    }
  }
  return {
    url: `${directBaseUrl}/chat/completions`,
    body: buildChatPayload(model.id, content, outputTokens),
  }
}

function proxyBody(
  model: Model,
  content: string,
  outputTokens: number,
): { url: string; body: unknown } {
  return {
    url: `${proxyUrl}/v1/chat/completions`,
    body: buildChatPayload(model.id, content, outputTokens),
  }
}

function safeHeaders(response: Response): Record<string, string> {
  const names = [
    "x-copilot-service-request-id",
    "x-github-request-id",
    "x-ratelimit-limit",
    "x-ratelimit-remaining",
    "retry-after",
  ]
  return Object.fromEntries(
    names.flatMap((name) => {
      const value = response.headers.get(name)
      return value ? [[name, value]] : []
    }),
  )
}

async function runRequest(
  probeCase: ProbeCase,
  dimension: "direct" | "proxy",
  target: { url: string; body: unknown },
): Promise<ProbeResult> {
  const started = Date.now()
  try {
    const { response, body, text } = await fetchJson(target.url, {
      method: "POST",
      headers:
        dimension === "direct" ?
          copilotHeaders(state)
        : { "content-type": "application/json", authorization: "Bearer dummy" },
      body: JSON.stringify(target.body),
    })
    const errorObject =
      body && typeof body === "object" ?
        (body as Record<string, unknown>).error
      : undefined
    return {
      case: probeCase.name,
      dimension,
      status: response.status,
      ok: response.ok,
      error:
        response.ok ? undefined : (
          JSON.stringify(errorObject ?? body ?? text.slice(0, 500))
        ),
      usage: extractUsage(body),
      copilotUsage: extractCopilotUsage(body),
      durationMs: Date.now() - started,
      headers: safeHeaders(response),
    }
  } catch (error) {
    return {
      case: probeCase.name,
      dimension,
      status: null,
      ok: false,
      error: error instanceof Error ? error.message : String(error),
      durationMs: Date.now() - started,
      headers: {},
    }
  }
}

interface PreparedCase {
  probeCase: ProbeCase
  content: string
  estimatedTokens: number
}

interface ReportRow {
  case: string
  estimatedInputTokens: number
  requestedOutputTokens: number
  classification: string
  direct?: ProbeResult
  proxy?: ProbeResult
  [key: string]: unknown
}

interface ContextReport {
  generatedAt: string
  executed: boolean
  model: Model
  endpoint: string
  via: string
  margin: number
  results: Array<ReportRow>
  usageBefore: unknown
  usageAfter: unknown
  creditDelta?: number
  costAttribution: string
}

function formatResult(result?: ProbeResult): string {
  if (!result) return "—"
  return String(result.status ?? result.error ?? "unknown")
}

function renderMarkdown(report: ContextReport): string {
  const lines = [
    `# Context Boundary Report — ${report.generatedAt}`,
    "",
    `- Model: \`${report.model.id}\``,
    `- Endpoint: \`${report.endpoint}\``,
    `- Executed: ${String(report.executed)}`,
    `- Cost attribution: ${report.costAttribution}`,
    `- Observed account credit delta: ${String(report.creditDelta ?? "unavailable")}`,
    "",
    "| Case | Estimate | Output requested | Direct | Proxy | Direct AIU | Proxy AIU | Classification |",
    "|---|---:|---:|---|---|---:|---:|---|",
  ]
  for (const item of report.results) {
    const directAiu =
      item.direct?.copilotUsage ?
        nanoAiuToAiu(item.direct.copilotUsage.total_nano_aiu).toFixed(6)
      : "—"
    const proxyAiu =
      item.proxy?.copilotUsage ?
        nanoAiuToAiu(item.proxy.copilotUsage.total_nano_aiu).toFixed(6)
      : "—"
    lines.push(
      `| ${item.case} | ${item.estimatedInputTokens} | ${item.requestedOutputTokens} | ${formatResult(item.direct)} | ${formatResult(item.proxy)} | ${directAiu} | ${proxyAiu} | ${item.classification} |`,
    )
  }
  lines.push(
    "",
    "## Caveats",
    "",
    "- Local token counts are estimates; provider usage is authoritative when returned.",
    "- Credit delta is account-level and may include concurrent activity or delayed accounting.",
    "- Per-request AIU is derived from provider-returned nano-AIU; no AIU-to-AIC conversion was inferred.",
  )
  return lines.join("\n")
}

async function prepareCases(
  model: Model,
  cases: Array<ProbeCase>,
): Promise<Array<PreparedCase>> {
  const prepared: Array<PreparedCase> = []
  for (const probeCase of cases) {
    if (probeCase.expectation === "not-applicable") {
      prepared.push({ probeCase, content: "", estimatedTokens: 0 })
      continue
    }
    const calibrated = await calibratePrompt(
      probeCase.targetInputTokens,
      async (content) => {
        const count = await getTokenCount(
          buildChatPayload(model.id, content, probeCase.requestedOutputTokens),
          model,
        )
        return count.input
      },
    )
    prepared.push({
      probeCase,
      content: calibrated.content,
      estimatedTokens: calibrated.estimatedTokens,
    })
  }
  return prepared
}

async function executeMatrix(
  model: Model,
  prepared: Array<PreparedCase>,
): Promise<Array<ReportRow>> {
  const results: Array<ReportRow> = []
  for (const item of prepared) {
    if (item.probeCase.expectation === "not-applicable") {
      results.push({
        case: item.probeCase.name,
        estimatedInputTokens: 0,
        requestedOutputTokens: 0,
        classification: "not-applicable",
        reason: item.probeCase.reason,
      })
      continue
    }
    let direct: ProbeResult | undefined
    let proxy: ProbeResult | undefined
    if (via === "direct" || via === "both") {
      direct = await runRequest(
        item.probeCase,
        "direct",
        directBody(model, item.content, item.probeCase.requestedOutputTokens),
      )
    }
    if (via === "proxy" || via === "both") {
      proxy = await runRequest(
        item.probeCase,
        "proxy",
        proxyBody(model, item.content, item.probeCase.requestedOutputTokens),
      )
    }
    results.push({
      case: item.probeCase.name,
      expectation: item.probeCase.expectation,
      targetInputTokens: item.probeCase.targetInputTokens,
      estimatedInputTokens: item.estimatedTokens,
      requestedOutputTokens: item.probeCase.requestedOutputTokens,
      direct,
      proxy,
      classification: classifyPair(direct, proxy),
    })
  }
  return results
}

function directBaseFromToken(token: string): string {
  const proxyClaim = token
    .split(";")
    .find((part) => part.startsWith("proxy-ep="))
    ?.slice("proxy-ep=".length)
  if (!proxyClaim) return "https://api.githubcopilot.com"
  return `https://${proxyClaim.replace(/^proxy\./, "api.")}`
}

function quotaSnapshot(usage: unknown): unknown {
  if (!usage || typeof usage !== "object") return undefined
  const record = usage as Record<string, unknown>
  return {
    copilot_plan: record.copilot_plan,
    quota_reset_date: record.quota_reset_date,
    token_based_billing: record.token_based_billing,
    premium_interactions:
      record.quota_snapshots && typeof record.quota_snapshots === "object" ?
        (record.quota_snapshots as Record<string, unknown>).premium_interactions
      : undefined,
  }
}

async function writeReports(report: ContextReport): Promise<void> {
  const reportDir = join(import.meta.dir, "reports", "context-boundary")
  await mkdir(reportDir, { recursive: true })
  const stamp = report.generatedAt.replaceAll(/[:.]/g, "-")
  const json = `${JSON.stringify(report, null, 2)}\n`
  const markdown = `${renderMarkdown(report)}\n`
  await Promise.all([
    writeFile(join(reportDir, `${stamp}.json`), json),
    writeFile(join(reportDir, `${stamp}.md`), markdown),
    writeFile(join(reportDir, "latest.json"), json),
    writeFile(join(reportDir, "latest.md"), markdown),
  ])
  console.log(`Reports written to ${reportDir}`)
}

async function main(): Promise<void> {
  const catalogResponse = await fetchJson(`${proxyUrl}/v1/models`, {
    headers: { authorization: "Bearer dummy" },
  })
  if (!catalogResponse.response.ok)
    throw new Error(
      `Failed to load proxy catalog: ${catalogResponse.response.status}`,
    )
  const models = catalogResponse.body as ModelsResponse
  const model = chooseModel(models)
  const endpoint = resolveEndpoint(model.id, models)
  const cases = buildProbeCases(model, margin).filter((item) =>
    selectedCases.has(item.name),
  )
  const prepared = await prepareCases(model, cases)

  console.log(
    JSON.stringify(
      {
        execute,
        model: model.id,
        endpoint,
        limits: model.capabilities.limits,
        cases: prepared.map((item) => ({
          case: item.probeCase.name,
          estimate: item.estimatedTokens,
          output: item.probeCase.requestedOutputTokens,
          expectation: item.probeCase.expectation,
        })),
      },
      null,
      2,
    ),
  )
  if (!execute) {
    console.log(
      "Dry run only. Re-run with --execute to send the minimal matrix.",
    )
    return
  }

  const githubToken = (
    await readFile(
      join(homedir(), ".local", "share", "copilot-api", "github_token"),
      "utf8",
    )
  ).trim()
  state.githubToken = githubToken
  const tokenResponse = await getCopilotToken()
  state.copilotToken = tokenResponse.token
  directBaseUrl = directBaseFromToken(tokenResponse.token)

  const beforeUsage = (await fetchJson(`${proxyUrl}/usage`)).body
  const results = await executeMatrix(model, prepared)
  const afterUsage = (await fetchJson(`${proxyUrl}/usage`)).body
  const delta = creditDelta(beforeUsage, afterUsage)
  const report: ContextReport = {
    generatedAt: new Date().toISOString(),
    executed: true,
    model,
    endpoint,
    via,
    margin,
    results,
    usageBefore: quotaSnapshot(beforeUsage),
    usageAfter: quotaSnapshot(afterUsage),
    creditDelta: delta,
    costAttribution: delta === undefined ? "unavailable" : "account-delta-only",
  }
  await writeReports(report)
}

await main()

/**
 * Shared helpers for standalone proxy validation scripts (see
 * scripts/proxy-model-validation.ts). Not part of the shipped server: this
 * module authenticates directly against the upstream Copilot API (bypassing
 * the local proxy), fetches and classifies the model catalog, and provides
 * small header/formatting helpers used to build the 3-dimension
 * (direct / proxy-messages / proxy-chat) blame matrix report.
 *
 * Uses the same building blocks as scripts/context-boundary-validation.ts:
 * the persisted GitHub token is exchanged for a Copilot token via
 * ~/services/github/get-copilot-token, and headers are built with the real
 * ~/lib/api-config helpers so requests look identical to what the shipped
 * server sends.
 */

import { readFile } from "node:fs/promises"

import type { UpstreamEndpoint } from "~/lib/endpoint-routing"
import type { Model, ModelsResponse } from "~/services/copilot/get-models"

import { copilotHeaders as buildCopilotHeaders } from "~/lib/api-config"
import { resolveEndpoint } from "~/lib/endpoint-routing"
import { PATHS } from "~/lib/paths"
import { state } from "~/lib/state"
import { getCopilotToken } from "~/services/github/get-copilot-token"

export type CopilotModel = Model

export interface ModelProfile {
  id: string
  endpoint: UpstreamEndpoint
  isClaude: boolean
  toolSupport: boolean
  thinkingSupport: "adaptive" | "enabled-only" | "none"
  effortSupport: "param" | "none"
  temperatureSupport: boolean
  maxOutputTokens: number
}

export interface TestResult {
  test: string
  model: string
  endpoint: string
  status: "pass" | "fail" | "skip"
  detail?: string
  durationMs: number
}

/** Direct (non-proxied) upstream Copilot API base URL. */
export const COPILOT_API_BASE_URL =
  process.env.COPILOT_API_BASE_URL ?? "https://api.githubcopilot.com"

/** Local copilot-api proxy base URL. */
export const PROXY_URL = (
  process.env.PROXY_URL ?? "http://localhost:4141"
).replace(/\/$/, "")

/**
 * Authenticate using the GitHub token persisted by `copilot-api auth`,
 * exchange it for a Copilot token, and return that token — the "jwt" used
 * to call the upstream Copilot API directly.
 */
export async function getJwt(): Promise<string> {
  const githubToken = (await readFile(PATHS.GITHUB_TOKEN_PATH, "utf8")).trim()
  if (!githubToken) {
    throw new Error(
      `No GitHub token found at ${PATHS.GITHUB_TOKEN_PATH}. Run 'bun run dev auth' first.`,
    )
  }
  state.githubToken = githubToken
  const tokenResponse = await getCopilotToken()
  state.copilotToken = tokenResponse.token
  return tokenResponse.token
}

/** Build headers for a direct (non-proxied) request to the Copilot API. */
export function copilotHeaders(jwt: string): Record<string, string> {
  state.copilotToken = jwt
  return buildCopilotHeaders(state)
}

/** Build headers for a request to the local proxy's /v1/messages endpoint. */
export function proxyHeaders(): Record<string, string> {
  return {
    "content-type": "application/json",
    "x-api-key": "dummy",
    "anthropic-version": "2023-06-01",
  }
}

/** Fetch the full model catalog directly from the upstream Copilot API. */
export async function fetchModels(jwt: string): Promise<Array<CopilotModel>> {
  const response = await fetch(`${COPILOT_API_BASE_URL}/models`, {
    headers: copilotHeaders(jwt),
  })
  if (!response.ok) {
    throw new Error(`Failed to fetch models: HTTP ${response.status}`)
  }
  const body = (await response.json()) as ModelsResponse
  return body.data
}

/** Keep only chat-completion models (drop embeddings and other non-chat types). */
export function filterChatModels(
  models: Array<CopilotModel>,
): Array<CopilotModel> {
  return models.filter((model) => model.capabilities.type === "chat")
}

/**
 * Capability fields the live catalog advertises but that the shared `Model`
 * type (src/services/copilot/get-models.ts) doesn't declare, because
 * production code doesn't consume them yet (see `ModelSupports`).
 */
type ModelSupports = Model["capabilities"]["supports"]
interface ExtendedSupports extends ModelSupports {
  adaptive_thinking?: boolean
}

/** Classify a model's proxy-relevant capabilities for the validation report. */
export function classifyModel(model: CopilotModel): ModelProfile {
  const catalog: ModelsResponse = { object: "list", data: [model] }
  const endpoint = resolveEndpoint(model.id, catalog)
  const isClaude = model.id.startsWith("claude-")
  const supports = model.capabilities.supports
  const extended: ExtendedSupports = supports

  let thinkingSupport: ModelProfile["thinkingSupport"] = "none"
  if (isClaude) {
    thinkingSupport = extended.adaptive_thinking ? "adaptive" : "enabled-only"
  }

  return {
    id: model.id,
    endpoint,
    isClaude,
    // Default to true so an unadvertised capability is probed and reported
    // rather than silently skipped — this is a discovery tool.
    toolSupport: supports.tool_calls ?? true,
    thinkingSupport,
    effortSupport:
      (supports.reasoning_effort?.length ?? 0) > 0 ? "param" : "none",
    temperatureSupport: endpoint !== "/responses",
    maxOutputTokens: model.capabilities.limits?.max_output_tokens ?? 0,
  }
}

/** Format a millisecond duration for compact report tables. */
export function fmtMs(ms: number): string {
  return ms < 1000 ? `${Math.round(ms)}ms` : `${(ms / 1000).toFixed(2)}s`
}

